$connect=static fn(string $db)=>new PDO("mysql:host={$host};port={$port};dbname={$db};charset=utf8mb4",'root',$password,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
$legacyBootstrap=static function(PDO $db)use($legacySchema,$migration002):void{
    $db->exec($legacySchema);$migration002($db);
    $db->exec("CREATE TABLE app_settings(setting_key VARCHAR(100) PRIMARY KEY,setting_value TEXT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB");
    $db->exec("CREATE TABLE mobile_access_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip_address VARCHAR(64) NOT NULL UNIQUE,user_agent VARCHAR(500),last_seen DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
    $cols=$db->query('SHOW COLUMNS FROM message_templates')->fetchAll(PDO::FETCH_COLUMN);
    if(!in_array('category',$cols,true))$db->exec("ALTER TABLE message_templates ADD category VARCHAR(50) NOT NULL DEFAULT 'Aviso' AFTER name");
    if(!in_array('title',$cols,true))$db->exec('ALTER TABLE message_templates ADD title VARCHAR(160) NULL AFTER category');
};
$counts=static function(PDO $db):array{$out=[];foreach(['users','cycles','participants','contributions','payouts','app_settings','message_queue','payment_receipts']as$t)$out[$t]=(int)$db->query("SELECT COUNT(*) FROM `{$t}`")->fetchColumn();return$out;};
