$legacy=$connect('gda_2a1_legacy');$legacyBootstrap($legacy);
$legacy->exec("INSERT INTO users(name,email,password,role)VALUES('Admin legado','legacy@example.test','hash','client_admin');INSERT INTO cycles(name,year,month,daily_amount,admin_pays,status)VALUES('Caixa legado',2026,7,20,0,'active');INSERT INTO participants(name,access_token)VALUES('Administração','token-admin'),('Participante teste','token-test');INSERT INTO cycle_participants VALUES(1,1,NOW()),(1,2,NOW());INSERT INTO cycle_points(cycle_id,day,participant_id)VALUES(1,1,1),(1,2,2);INSERT INTO contributions(cycle_id,participant_id,amount,paid_at,created_by)VALUES(1,2,20,NOW(),1);INSERT INTO payouts(cycle_id,point_day,participant_id,amount,status,created_by)VALUES(1,2,2,580,'paid',1);INSERT INTO app_settings VALUES('pix_key','test-key',NOW());INSERT INTO message_templates(cycle_id,code,name,category,body)VALUES(1,'test','Teste','Aviso','Mensagem');INSERT INTO message_queue(cycle_id,participant_id,template_code,message_text)VALUES(1,2,'test','Mensagem teste');INSERT INTO payment_receipts(cycle_id,participant_id,amount,paid_at,original_name,stored_name,mime_type,file_size)VALUES(1,2,20,NOW(),'receipt.pdf','test.pdf','application/pdf',10);");
