$assert($companyId>0,'Empresa legada ausente.');foreach(['users','cycles','participants','app_settings']as$t)$assert((int)$legacy->query("SELECT COUNT(*) FROM `{$t}` WHERE company_id IS NULL")->fetchColumn()===0,"{$t} sem empresa.");
$assert((string)$legacy->query("SELECT role FROM users WHERE id=1")->fetchColumn()==='client_admin','Papel legado incorreto.');
$snapshot=$legacy->query("SELECT identifier,name,status FROM companies ORDER BY id")->fetchAll();$migration003($legacy);$afterSecond=$counts($legacy);$assert($snapshot===$legacy->query("SELECT identifier,name,status FROM companies ORDER BY id")->fetchAll(),'Reexecução alterou empresas.');$assert($before===$afterFirst&&$afterFirst===$afterSecond,'Contagens mudaram na migração.');
$migration004($legacy);

$empty=$connect('gda_2a1_empty');$legacyBootstrap($empty);$migration003($empty);$migration003($empty);$assert((int)$empty->query('SELECT COUNT(*) FROM companies')->fetchColumn()===0,'Base vazia criou empresa.');$assert((int)$empty->query('SELECT COUNT(*) FROM users')->fetchColumn()===0,'Base vazia criou usuário.');$assert((int)$empty->query("SELECT COUNT(*) FROM users WHERE role='global_admin'")->fetchColumn()===0,'Base vazia criou global admin.');

$partial=$connect('gda_2a1_partial');$legacyBootstrap($partial);$partial->exec("CREATE TABLE companies(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL)ENGINE=InnoDB;INSERT INTO companies(name)VALUES('Cliente parcial');ALTER TABLE users ADD company_id INT UNSIGNED NULL AFTER id;INSERT INTO users(company_id,name,email,password,role)VALUES(1,'Parcial','partial@example.test','hash','client_admin');INSERT INTO cycles(name,year,month,daily_amount,status)VALUES('Sem vínculo',2026,7,10,'active');");$migration003($partial);$migration003($partial);$assert((int)$partial->query('SELECT COUNT(*) FROM companies')->fetchColumn()===2,'Cenário parcial duplicou/perdeu empresas.');$assert((int)$partial->query('SELECT COUNT(*) FROM cycles WHERE company_id IS NULL')->fetchColumn()===0,'Ciclo parcial não vinculado.');

$failure=$connect('gda_2a1_failure');$legacyBootstrap($failure);$failure->exec("CREATE TABLE migration_test_errors(id INT AUTO_INCREMENT PRIMARY KEY,migration VARCHAR(190),error_message VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)ENGINE=InnoDB;INSERT INTO users(name,email,password,role)VALUES('Falha','failure@example.test','hash','client_admin');CREATE TABLE tenant_migration_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,migration VARCHAR(190),event VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)ENGINE=InnoDB");$failed=false;try{$migration003($failure);}catch(Throwable $e){$failed=true;$safeError=preg_replace('/(password|pwd)\s*=\s*[^ ;]+/i','$1=[redacted]',$e->getMessage());$log=$failure->prepare('INSERT INTO migration_test_errors(migration,error_message)VALUES(?,?)');$log->execute(['003_multi_tenant_foundation.php',mb_substr($safeError,0,500)]);}$assert($failed,'Falha controlada não ocorreu.');$assert((int)$failure->query('SELECT COUNT(*) FROM migration_test_errors')->fetchColumn()===1,'Falha não registrada.');$failure->exec('ALTER TABLE tenant_migration_log ADD company_id INT UNSIGNED NULL, ADD UNIQUE KEY uniq_tenant_migration_event(migration,event)');$migration003($failure);$migration003($failure);$assert((int)$failure->query('SELECT COUNT(*) FROM users WHERE company_id IS NULL')->fetchColumn()===0,'Retomada não vinculou usuário.');

$legacy->exec("INSERT INTO companies(name,identifier,status)VALUES('Cliente B','client-b','active'),('Inativa','inactive','inactive');SET @b=(SELECT id FROM companies WHERE identifier='client-b');SET @inactive=(SELECT id FROM companies WHERE identifier='inactive');INSERT INTO users(company_id,name,email,password,role)VALUES(@b,'Admin B','b@example.test','hash','client_admin'),(NULL,'Sem empresa','none@example.test','hash','client_admin'),(@inactive,'Inativo','inactive@example.test','hash','client_admin');INSERT INTO cycles(company_id,name,year,month,daily_amount,status)VALUES(@b,'Caixa B',2026,7,30,'active');INSERT INTO participants(company_id,name,access_token)VALUES(@b,'Participante B','token-b');INSERT INTO contributions(cycle_id,participant_id,amount,paid_at,created_by)VALUES(2,3,30,NOW(),2);INSERT INTO message_queue(cycle_id,participant_id,template_code,message_text)VALUES(2,3,'test','Mensagem B');INSERT INTO app_settings(company_id,setting_key,setting_value)VALUES(@b,'pix_key','b-key');");
$_SESSION=['auth_scope'=>'client','user'=>['id'=>1,'role'=>'client_admin','company_id'=>$companyId]];$_GET['company_id']=2;$_POST['company_id']=2;$context=ClientContext::fromAuthenticatedSession();$assert($context->companyId()===$companyId,'Parâmetro alterou contexto.');(new RequireClientContextMiddleware($legacy,$context))->handle();
$assert((new CycleRepository($legacy,$context))->active(2)['id']===1,'Ciclo B exposto.');$assert((new ParticipantRepository($legacy,$context))->find(3)===null,'Participante B exposto.');$contributions=new ContributionRepository($legacy,$context);$assert($contributions->find(2)===null,'Contribuição B exposta.');$assert(!$contributions->delete(2),'Contribuição B alterada.');$assert(count((new MessageService())->queueForCompany($legacy,$context))===1,'Mensagens cruzaram empresas.');$settings=$legacy->prepare('SELECT setting_value FROM app_settings WHERE company_id=? AND setting_key=?');$settings->execute([$context->companyId(),'pix_key']);$assert($settings->fetchColumn()==='test-key','Configuração cruzou empresas.');(new BackupService())->assertBelongsToCompany(['company_id'=>$companyId],$context);$assert(true,'Backup próprio rejeitado.');$blocked=static function(callable $fn):bool{try{$fn();return false;}catch(Throwable){return true;}};$assert($blocked(fn()=>(new BackupService())->assertBelongsToCompany(['company_id'=>2],$context)),'Backup B aceito.');
$noneId=(int)$legacy->query("SELECT id FROM users WHERE email='none@example.test'")->fetchColumn();$_SESSION=['auth_scope'=>'client','user'=>['id'=>$noneId,'role'=>'client_admin','company_id'=>null]];$assert($blocked(fn()=>(new RequireClientContextMiddleware($legacy,ClientContext::fromAuthenticatedSession()))->handle()),'Usuário sem empresa aceito.');$inactiveUser=$legacy->query("SELECT id,company_id FROM users WHERE email='inactive@example.test'")->fetch();$_SESSION=['auth_scope'=>'client','user'=>['id'=>(int)$inactiveUser['id'],'role'=>'client_admin','company_id'=>(int)$inactiveUser['company_id']]];$assert($blocked(fn()=>(new RequireClientContextMiddleware($legacy,ClientContext::fromAuthenticatedSession()))->handle()),'Empresa inativa aceita.');

$meta=$legacy->query("SELECT TABLE_NAME,ENGINE,TABLE_COLLATION FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN('companies','tenant_migration_log') ORDER BY TABLE_NAME")->fetchAll();
