echo json_encode(['mariadb_version'=>$server->query('SELECT VERSION()')->fetchColumn(),'databases'=>$databases,'before'=>$before,'after_first'=>$afterFirst,'after_second'=>$afterSecond,'legacy_company_id'=>$companyId,'empty_companies'=>(int)$empty->query('SELECT COUNT(*) FROM companies')->fetchColumn(),'partial_companies'=>(int)$partial->query('SELECT COUNT(*) FROM companies')->fetchColumn(),'controlled_failure'=>$failed,'controlled_error'=>$safeError??null,'failure_log_entries'=>(int)$failure->query('SELECT COUNT(*) FROM migration_test_errors')->fetchColumn(),'tables'=>$meta,'companies_columns'=>$companyColumns,'company_foreign_keys'=>$fks,'company_nullability'=>$nullability,'isolation'=>'passed'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;
